Fixes: a6a6fe27bab4 ("net/smc: Dynamic control handshake limitation by socket options")
Signed-off-by: Nicolò Coccia <n.coccia96@gmail.com>
Reviewed-by: Dust Li <dust.li@linux.alibaba.com>
Tested-by: Dust Li <dust.li@linux.alibaba.com>
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The function __smc_setsockopt() in net/smc/af_smc.c calls copy_from_sockptr() while holding lock_sock(sk). This allows a local attacker to cause a denial of service by passing a memory address that triggers a page fault (e.g., via userfaultfd or FUSE), causing the copy operation to sleep and hold the socket lock indefinitely, leading to hung tasks and exhaustion of kernel workqueues.

Here is the patch:

 static int __smc_setsockopt(struct socket *sock, int level, int optname,
 			    sockptr_t optval, unsigned int optlen)
 {
 	struct sock *sk = sock->sk;
 	struct smc_sock *smc;
 	int val, rc;

 	smc = smc_sk(sk);

+	/* pre-fetch user data outside the lock */
+	if (optname == SMC_LIMIT_HS) {
+		if (optlen < sizeof(int))
+			return -EINVAL;
+		if (copy_from_sockptr(&val, optval, sizeof(int)))
+			return -EFAULT;
+	}
+
 	lock_sock(sk);
 	switch (optname) {
 	case SMC_LIMIT_HS:
-		if (optlen < sizeof(int)) {
-			rc = -EINVAL;
-			break;
-		}
-		if (copy_from_sockptr(&val, optval, sizeof(int))) {
-			rc = -EFAULT;
-			break;
-		}
-
 		smc->limit_smc_hs = !!val;
 		rc = 0;
 		break;
 	default:
 		rc = -EOPNOTSUPP;
 		break;
 	}
 	release_sock(sk);

 	return rc;
 }



