-			rc = -EINVAL;
-			break;
-		}
-		if (copy_from_sockptr(&val, optval, sizeof(int))) {
-			rc = -EFAULT;
-			break;
-		}
-
		smc->limit_smc_hs = !!val;
		rc = 0;
		break;
...
	}
	release_sock(sk);

Reason:
The user-space copy (`copy_from_sockptr`) is moved outside the `lock_sock()` critical section for the `SMC_LIMIT_HS` option. This prevents the socket lock from being held during a potential blocking copy operation, eliminating the sleep-inside-lock vulnerability. The copy now occurs before acquiring the lock, so any page fault or sleep during the copy does not hold the lock, avoiding the DoS.

